import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Recording","description":"","frontmatter":{},"headers":[],"relativePath":"INSTALLING_RECORDING.md","filePath":"INSTALLING_RECORDING.md"}'),r={name:"INSTALLING_RECORDING.md"};function i(n,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="recording" tabindex="-1">Recording <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Recording&quot;">​</a></h1><p>This page covers installing and setting up what the demo recorder needs before its first take. <a href="./RECORDING">Recording</a>, the chapter on making videos, covers the takes themselves.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ol><li><p><strong>A MIDI port the DAW listens on.</strong> This is the IAC bus, as <a href="./MIDI_SETUP">MIDI Setup</a> describes, with a Live set holding a MIDI track for each channel used. The first track of a set plays on channel 1, the second on channel 2 and so on, so a Live set with a track listening to <code>IAC Driver Bus 1</code> on each of channels 1 to 4 covers a demo with four tracks. Each Live track&#39;s Monitor switch must be set to <strong>In</strong>. A take through FluidSynth needs none of this.</p></li><li><p><strong>A loopback audio device.</strong> A Mac can&#39;t record what comes out of its speakers by itself, so the recorder records from BlackHole 2ch, a free, open-source loopback device. Install it from the project folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_blackhole.sh</span></span></code></pre></div><p>The script uses Homebrew, offering to install it first, and asks before installing BlackHole, an audio driver, for which macOS asks your password and restarts the audio; it does nothing when BlackHole is installed already, and ends by saying how to make the Multi-Output Device below. BlackHole can also be installed by hand from <a href="https://existential.audio/blackhole/" target="_blank" rel="noreferrer">https://existential.audio/blackhole/</a>, the 2-channel build. After installing, macOS may ask you to allow the driver in System Settings under Privacy &amp; Security.</p></li><li><p><strong>A Multi-Output Device</strong>, so that you hear the DAW while the take is recorded. In Audio MIDI Setup, press <code>+</code> at the bottom left, choose <strong>Create Multi-Output Device</strong>, and tick your speakers or headphones and <strong>BlackHole 2ch</strong>. Tick <strong>Drift Correction</strong> on BlackHole. In the DAW&#39;s audio preferences, choose that Multi-Output Device as the output. The DAW now plays into your speakers and into BlackHole at once, and the recorder reads BlackHole.</p></li><li><p><strong>Screen Recording permission</strong> for your terminal program. The first take asks for it; after allowing it in System Settings under Privacy &amp; Security, quit and reopen the terminal, since the permission reaches new processes only.</p></li><li><p><strong>Xcode&#39;s command line tools</strong>, which most Macs that build software already have, for the <code>swift</code> command the recorder uses once per take to find BlackHole&#39;s id:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xcode-select --install</span></span></code></pre></div></li></ol>',4)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
